        /// </summary>
        [CozySearchable]
        [Tooltip("Sets the intensity of the sun light at a certain time. Starts and ends at midnight.")]
        [AtmosphereProperty(VarType.Float, "LightIntensity")]
        public AtmosphereProperty<FloatValue> lightIntensity;
        /// <summary>
        /// Determines the type of shadows used for this light.
        /// </summary>
        [CozySearchable]
        [Tooltip("Determines the type of shadows used for this light.")]
        [AtmosphereProperty(VarType.Enum, "ShadowType")]
        public AtmosphereProperty<EnumValue<LightShadows>> shadowType;
        /// <summary>
        /// Set the intensity of the sun light shadows
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the intensity of the sun light shadows")]
        [AtmosphereProperty(VarType.Float, "ShadowIntensity", minFloat = 0, maxFloat = 1)]
        public AtmosphereProperty<FloatValue> shadowIntensity;

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float time) {
            if (!active) return;
            lightColor.SetValue(ref parameters.lightingSunLightColor, time);
            lightIntensity.SetValue(ref parameters.lightingSunLightIntensity, time);
            shadowType.SetValue(ref parameters.lightingSunShadowType, time);
            shadowIntensity.SetValue(ref parameters.lightingSunShadowIntensity, time);
        }

        public override void ResetToDefaults() {
        }

        public override void CopyModel(AtmosphereModel model) {
                lightColor = model.lightingSunLightColor;
                lightIntensity = model.lightingSunLightIntensity;
                shadowType = model.lightingSunShadowType;
                shadowIntensity = model.lightingSunShadowIntensity;
        }

        public override void ApplyAsBiome(AtmosphereParameters parameters, float time, float weight) {
            if (!active || weight == 0) return;
            parameters.lightingSunLightColor.Lerp(lightColor.GetValue(parameters.lightingSunLightColor, time), weight);
            parameters.lightingSunLightIntensity.Lerp(lightIntensity.GetValue(parameters.lightingSunLightIntensity, time), weight);
            parameters.lightingSunShadowType.Lerp(shadowType.GetValue(parameters.lightingSunShadowType, time), weight);
            parameters.lightingSunShadowIntensity.Lerp(shadowIntensity.GetValue(parameters.lightingSunShadowIntensity, time), weight);
        }

        public override void ApplyToModel(AtmosphereModel model) {
             if (!FeatureEnabledGlobally || !active) return;
            if (lightColor.overrideValue)
                model.lightingSunLightColor = lightColor;
            if (lightIntensity.overrideValue)
                model.lightingSunLightIntensity = lightIntensity;
            if (shadowType.overrideValue)
                model.lightingSunShadowType = shadowType;
            if (shadowIntensity.overrideValue)
                model.lightingSunShadowIntensity = shadowIntensity;
